#include <string>
#include <openssl/md5.h>

std::string computeUValue(std::string const& user_password, QPDF::EncryptionData const& data) {
    // Generate encryption key from user_password and data
    std::string padded_password = user_password;
    // Pad the password with null bytes to 32 bytes
    padded_password.resize(32, '\0');

    // Concatenate padded password with the first element of the encryption ID
    std::string input = padded_password + data.getID()[0];

    // Compute MD5 digest
    unsigned char md5_digest[MD5_DIGEST_LENGTH];
    MD5_CTX context;
    MD5_Init(&context);
    MD5_Update(&context, input.c_str(), input.length());
    MD5_Final(md5_digest, &context);

    // Run RC4 on the digest
    unsigned char rc4_key[MD5_DIGEST_LENGTH];
    std::copy(std::begin(md5_digest), std::end(md5_digest), std::begin(rc4_key));

    unsigned char rc4_state[256];
    unsigned char rc4_x = 0, rc4_y = 0;
    for (unsigned char i = 0; i < 256; ++i)
        rc4_state[i] = i;
    for (unsigned char i = 0; i < 256; ++i) {
        rc4_x = (rc4_x + rc4_state[i] + rc4_key[i % MD5_DIGEST_LENGTH]) % 256;
        std::swap(rc4_state[i], rc4_state[rc4_x]);
    }

    // Apply RC4 to the digest to generate the U value
    std::string u_value;
    for (int i = 0; i < 16; ++i) {
        rc4_y = (rc4_y + rc4_state[rc4_x]) % 256;
        rc4_x = (rc4_x + rc4_state[rc4_x]) % 256;
        std::swap(rc4_state[rc4_x], rc4_state[rc4_y]);
        u_value.push_back(rc4_state[(rc4_state[rc4_x] + rc4_state[rc4_y]) % 256]);
    }

    return u_value;
}

